package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaUzDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Yomon qo'shnidan boshpana", "Allohim, doimiy yashash joyidagi yomon qo'shnidan panoh tilayman, chunki safardagi qo'shni davom etadi.", "Yomon qo'shnidan himoya qilish uchun.", "Payg'ambarimiz ﷺ bundan panoh so'rashni buyurdilar."),
        "dua_ishfi_abdak" to DuaText("Bemorning tiklanishi uchun", "Allohim, bandangga shifo ber, toki Sen uchun dushmanga duch kelsin yoki Sen uchun namozga yursin.", "Kasal odamga tashrif buyurganida.", "Payg'ambar ﷺ kasallar uchun shunday aytishni o'rgatgan."),
        "dua_la_mania" to DuaText("Siz bergan narsangizni hech kim to'xtata olmaydi", "Allohdan boshqa hech kim ibodat qilinishga loyiq emas, yolg'iz, sherigi yo'q. Mulk Uniki va hamd Unikidir va U har bir narsaga qodirdir. Allohim, sen berayotgan narsangni hech kim to'xtata olmaydi va sen bermagan narsangni hech kim bera olmaydi va boylarning mollari Sendan foyda yo'q.", "Farz namozining salomidan keyin.", "Payg'ambarimiz ﷺ har farz namozdan keyin buni aytdilar."),
        "dua_slaughtering" to DuaText("Hayvonni so'yganda", "Alloh nomi bilan va Alloh buyukdir.", "Hayvonni qurbonlik qilish yoki so'yish paytida.", "Payg'ambarimiz ﷺ qurbonlik vaqtida bismilloh va takbir aytdilar."),
        "dua_undressing" to DuaText("Kiyimni yechganda", "Alloh nomi bilan.", "Kiyimni yechayotganda (g'usl yoki almashtirish uchun).", "U jinlarning ko'zlari bilan odamning avrat joylari orasidagi pardaga aylanadi."),
        "dua_ilbas_jadidan" to DuaText("Yangi kiyimdagi odamni ko'rish", "Yangisini kiying, maqtovga loyiq yashang va shahid bo'lib o'ling.", "Musulmon birodarni yangi kiyimda ko'rishda.", "Rasululloh ﷺ Umar (RA) yangi kiyimda ko'rganlarida shu duoni qilganlar."),
        "dua_hajj_la_riya" to DuaText("O'zini ko'rsatishdan xoli Haj", "Allohim, ko'z-ko'z qilmay, shon-shuhratga intilmasdan haj qil.", "Hajga niyat qilishda ixlos uchun.", "Rasululloh ﷺ bu duoni haj vaqtida qilganlar."),
        "dua_q_muslimayni_laka" to DuaText("Ibrohim va Ismoil duolari (AS) — Bizni itoatkor qilgin", "Parvardigorimiz, bizlarni ham o‘zingga bo‘ysunuvchi, zurriyotimizdan esa o‘zingga bo‘ysunuvchi ummat qil. Bizga ibodatlarimizni ko'rsat va tavbalarimizni qabul qil. Albatta, Sen tavbalarni qabul qiluvchi va rahmlisan.", "O'zi va avlodlari uchun bo'ysunish duosi.", "Ka'bani qurishda qilingan duo."),
        "dua_q_iftah_baynana" to DuaText("Shu'ayb duosi (AS) — O'rtamizdagi hukm", "Ey Robbimiz, biz bilan qavmimiz oramizda haq bilan hukm qil, Sen hukm qiluvchilarning eng yaxshisisan.", "Haq va botil o'rtasidagi hukm uchun.", "Shuaybning duosi (AS). Qavmi uni yolg'onga chiqarganida."),
        "dua_q_la_akuna_zahiran" to DuaText("Muso alayhissalomning duosi (AS) - Hech qachon jinoyatchilarga yordamchi bo'lmang", "Parvardigorim, menga bergan ne’mating tufayli men hech qachon jinoyatchilarning yordamchisi bo‘lmayman.", "Allohning ne'matlariga shukr qilish va zolimlarga yordam bermaslikka qasam.", "Muso alayhissalomning tavba qilganidan keyin bay'ati (AS)."),
        "dua_q_nuh_unsurni" to DuaText("Nuh duosi (AS) - Menga yordam bering, ular Meni inkor etadilar", "Robbim, menga yordam ber, chunki ular meni yolg'onga chiqardilar.", "Odamlar sizni inkor etib, haqiqatni rad qilganda.", "Nuh duosi (AS), ijobat bo'ldi."),
        "dua_q_ihkum_bil_haqq" to DuaText("Rabbim, Haq bilan hukm qil", "Robbim, haq bilan hukm qil. Bizning Robbimiz rahmli zotdir, siz vasf qilgan narsangizdan yordam so'raladigan zotdir.", "Yolg'on va yolg'on ayblovlar oldida.", "Payg'ambarga o'rgatilgan duo ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Qarz va dushmanlardan boshpana", "Allohim, qarzga botib qolishdan, dushmanga mag'lub bo'lishdan va dushmanlarning g'azabidan panoh so'rayman.", "Qarz yukidan va dushmanlarning hukmronligidan himoya qilish.", "Payg'ambar ﷺ bu narsalardan panoh so'rar edi."),
        "dua_faqr_qillah_dhillah" to DuaText("Qashshoqlik va xorlikdan panoh", "Allohim, faqirlik, kamchilik va xorlikdan, boshqalarga zulm qilishdan yoki zulm qilinishidan Sendan panoh tilayman.", "Qiyinchilik, muhtojlik va xorlikdan omon bo'lish.", "Payg'ambar o'rgatgan panoh ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Kechirasiz, rahm-shafqat qiling, hidoyat qiling, shifo bering, ta'minlang", "Allohim, meni mag‘firat qil, rahm qil, hidoyat qil, menga yaxshilik ber va rizqlantirgin.", "Payg'ambar ﷺ bu duoni namoz bilan birga yangi musulmonlarga o'rgatgan.", "Payg'ambar ﷺ dedilar: Bu so'zlar siz uchun dunyo va oxiratni jamlaydi."),
        "dua_ruku_laka_raka_tu" to DuaText("Rukuda — Senga taʼzim qildim", "Allohim, Senga ta’zim qildim, Senga iymon keltirdim va Senga taslim bo‘ldim. Qulogʻim, koʻrishim, aqlim, suyaklarim va paylarim Senga boʻysunadi.", "Rukuda (ayniqsa, nafl namozlarda).", "Rasululloh ﷺ buni rukuda o'qidilar."),
        "dua_sujood_laka_sajadtu" to DuaText("Sujudda — Senga sajda qildim", "Allohim, Senga sajda qildim, Senga iymon keltirdim va Senga taslim boʻldim. Mening yuzim uni yaratgan, shakl bergan va eshitish va ko'rish qobiliyatini yaratgan zotga sajda qildi. Blessed is Allah, the best of creators.", "Sujudda (ayniqsa, nafl namozlarda).", "Rasululloh ﷺ buni sajda qilib o'qidilar."),
        "dua_ruku_sujood_subhanaka" to DuaText("Sen pok bo'ling, Rabbimiz, meni kechir", "Ey Robbimiz Allohim Senga pok va hamdu sanolar bo'lsin. Allohim, meni kechir.", "Ruku va sajdada.", "Oisha (RA): Rasululloh ﷺ ruku va sajdada tez-tez aytganlar."),
        "dua_q_musa_li_akhi" to DuaText("Muso alayhissalomning duosi (AS) - Meni va ukamni kechir", "Parvardigorim, meni va birodarimni mag‘firat qil va bizlarni o‘z rahmatingga kiritgin, chunki Sen rahmlilarning eng rahmlisisan.", "O'zini va birodarini yoki yaqinlarini kechirish.", "Musoning duosi (AS) Horun (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Ishimni Allohga topshirdim", "Va ishimni Allohga topshirdim. Albatta, Alloh bandalarini ko'rib turuvchidir.", "Odamlar sizga qarshi chiqsa va ish Allohga qolishi kerak.", "Fir'avn qavmidan mo'minning so'zlari; Keyin Alloh uni ularning yomon makrlaridan saqladi."),
        "dua_q_hawariyyun" to DuaText("Shogirdlarning duosi - bizni guvohlar bilan yozing", "Ey Robbimiz, biz nozil qilgan narsangga iymon keltirdik va Payg'ambarga ergashdik. Bas, bizni guvohlar qatorida yozgin.", "Iymonda va Payg'ambarga ergashishda sobit bo'lganligi uchun.", "Iso shogirdlarining duosi (AS)."),
        "dua_q_la_tukhzini" to DuaText("Ibrohim duosi (AS) — Meni sharmanda qilmang", "Va ular qayta tiriladigan kuni meni sharmanda qilmanglar.", "Qiyomat kuni sharmandalikdan omon bo'lish.", "Ibrohim alayhissalomning oxirat uchun duosi (AS)."),
        "dua_iftar_laka_sumtu" to DuaText("Iftorlik — Sen uchun ro'za tutdim", "Allohim, Sen uchun ro'za tutdim va Sening rizqing bilan iftor qildim.", "Ro'zani ochishda (mashhur iftor duosi).", "Payg'ambarimiz ﷺ iftorda aytdilar. Boshqa rivoyatlar bilan mustahkamlangan mursal rivoyatdir; iftorda o'qish hanafiylar va ko'pchilikning amalidir."),
        "dua_iftar_ibn_umar" to DuaText("Iftorlik — O'z rahmating ila, meni kechir", "Allohim, Sendan hamma narsani qamrab olgan rahmating ila meni mag'firat qilishingni so'rayman.", "Iftorda — Abdulloh ibn Amr (RA) duo qildilar; ro'zadorning iftordagi duosi rad etilmaydi.", "Hadis: Ro‘zadorning iftor vaqtidagi duosi rad etilmaydi."),
        "dua_inni_saim" to DuaText("Ro'za tutayotganda g'azablansa", "Men ro'zadorman, men ro'zadorman.", "Ro'za tutayotganda kimdir sizni haqorat qilsa yoki siz bilan janjallashsa.", "Payg'ambarimiz ﷺ dedilar: Ro'za qalqondir, shuning uchun ro'zador fahsh so'zlamasin yoki johillik qilmasin - kimdir janjal qilsa, buni ikki marta ayting."),
        "dua_eid_takbeer" to DuaText("Hayitga borishda takbir", "Alloh buyukdir, Alloh buyukdir, Allohdan o'zga iloh yo'q va Alloh buyukdir, Alloh eng buyukdir va barcha hamdlar Allohga bo'lsin.", "Oy ko‘rish kechasidan to Ramazon hayiti namozigacha, ayniqsa hayit maydoniga yo‘lda.", "Qur’oni karim: “To‘g‘risi, sanashni tugallang va Allohning buyukligini e’lon qiling” (Baqara, 185). Ibn Mas'ud (RA) bu takbirni aytgan."),
        "dua_ahsin_aqibatana" to DuaText("Oxiratimizni barcha ishlarda xayrli qilgin", "Allohim, barcha ishlarda oqibatimizni yaxshi qil, bu dunyoda sharmandalikdan, oxiratda azobdan saqlagin.", "Har bir masalada yaxshi natija uchun.", "Kim bu duoni o'qisa va imtihondan oldin vafot etsa, o'ladi (imtihondan omon)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Fazl va rahmatingdan so'rayman", "Allohim, Sendan fazling va rahmatingni so'rayman, chunki ularga Sendan boshqa hech kim ega emas.", "Rizq va rahmat so'raganda.", "Mehmonlar Payg'ambar ﷺ huzurlariga ovqat bo'lmaganda kelishdi; u bu duoni qildi, keyin sovg'a keldi."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Badaviyga o'rgatilgan so'zlar", "Allohdan boshqa hech kim ibodat qilinishga loyiq emas, yolg'iz, sherigi yo'q. Alloh buyuk va buyukdir. Allohga hamdu sanolar bo'lsin. Olamlarning Robbi Alloh pokdir. Qudratli va hikmatli Allohdan o'zga kuch va quvvat yo'q.", "Zikr va duoning keng qamrovli iborasi - badaviyga o'rgatilgan.", "Shundan keyin unga “Allohummag‘fir li varhamni vahdini varzuqni” deyish o‘rgatilgan."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Oldin va keyin yuborganlarimni kechir", "Allohim, oldin qilgan va keyin qilgan gunohlarimni, yashirin va oshkora qilgan gunohlarimni, haddan oshganlarimni va o'zing mendan ko'ra yaxshiroq biladigan gunohlarimni mag'firat et. Oldinga keltiruvchi ham, orqaga qaytaruvchi ham Sensan. Sendan o'zga iloh yo'q.", "Tashahhud va salovotdan keyin, salom oldidan.", "Payg'ambarimiz ﷺ buni namoz oxirida, tashahhud bilan salom orasida o'qidilar."),
        "dua_jiddi_wa_hazli" to DuaText("Mening jiddiyligim va hazilligimni kechir", "Allohim, meni jiddiy va masxara, xato va ataylab qilgan gunohlarimni kechirgin va bularning hammasi mening ichimda.", "Ma'lum va noma'lum har qanday gunoh uchun mag'firat.", "Payg'ambarning keng qamrovli istig'forlari ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Rukudan keyin — Osmonlarni toʻldirish hamd", "Ey Robbimiz, osmonlarni to'ldirish, yerni to'ldirish va undan keyin xohlagan narsangni to'ldirish ham Senga xosdir.", "Rukudan turgach, “Rabbana lakal-hamd” bilan birga.", "Rasululloh ﷺ rukudan turganlarida aytdilar."),
        "dua_istiftah_kabira" to DuaText("Alloh buyukdir, ulug'dir", "Alloh buyuk va buyukdir. Allohga hamdu sanolar bo'lsin. Ertayu kech Allohga tasbeh bo'lsin.", "Namozni boshlaganda (boshlovchi maqtovning bir shakli).", "Rasululloh ﷺ dedilar: U uchun jannat eshiklari ochildi."),
        "dua_q_ashku_bathhi" to DuaText("Yaqub duosi (AS) — Men faqat Allohga shikoyat qilaman", "Men dard va g‘amimdan faqat Allohga shikoyat qilaman.", "Chuqur qayg'u va ayriliqda.", "Ya'qub (AS) Yusufdan (AS) ajralganida aytgan."),
        "dua_q_khayrun_hafiza" to DuaText("Alloh eng yaxshi himoyachidir", "Alloh eng yaxshi himoyachidir va U rahmlilarning eng rahmlisidir.", "Bolalar yoki yaqinlaringizni sayohatga jo'natishda.", "Ya'qub (AS) o'g'lini Ollohga topshirayotganda shunday dedi."),
        "dua_q_aqraba_rashada" to DuaText("Robbim meni to'g'riga yaqinroq hidoyat qilsin", "Shoyadki, Robbim meni bundan ham yaqinroq bo'lgan narsaga hidoyat qilsa.", "Ba'zi masalada yaxshiroq yo'l izlayotganda.", "Payg'ambarimiz ﷺ unutganlarida aytishlari kerak."),
        "dua_q_sawa_as_sabil" to DuaText("Muso alayhissalomning duosi (AS) - Meni to'g'ri yo'lga boshla", "Shoyadki, Robbim meni to'g'ri yo'lga hidoyat qilur.", "Yangi sayohatga yoki notanish yo'lga chiqayotganda.", "Muso (AS) Madyan tomon burilib shunday dedi."),
        "dua_q_not_among_wrongdoers" to DuaText("Meni zolimlar qatoriga qo'yma", "Parvardigorim, meni zolim qavmlardan qilmagin.", "Allohdan zolimlardan saqlashini so'ragan duo.", "Allohdan zolimlardan saqlashini so'ragan duo."),
        "dua_q_do_not_make_us_trial" to DuaText("Bizni Sinovga aylantirmang", "Our Lord, do not make us a trial for the disbelievers, and forgive us, our Lord. Albatta, Sen aziz va hikmatli zotsan.", "Ibrohim duosi (AS) va uning sahobalari.", "Ibrohim duosi (AS) va uning sahobalari."),
        "dua_morning_witness" to DuaText("Tong shohidi Tavhid", "Allohim, Sening Arshing egalarini, farishtalaringni va butun maxluqotingni Sen Alloh ekaningga, Sendan o'zga iloh yo'q, yolg'iz, sheriging yo'qligiga va Muhammad ﷺ sening bandang va rasuling ekanligiga guvohlik berish uchun tongga kirdim.", "Rivoyatda ertalab to'rt marta aytish zikr qilingan.", "Rivoyatda ertalab to'rt marta aytish zikr qilingan."),
    )
}
